="wiki-odo",["receiptSHA256"]="382bf5354f10c97e49134f522f4a13e2527b4b22e35de17b8b48850c814fa4a5"},["location"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-odo",["receiptSHA256"]="382bf5354f10c97e49134f522f4a13e2527b4b22e35de17b8b48850c814fa4a5"},["relationships"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-odo",["receiptSHA256"]="382bf5354f10c97e49134f522f4a13e2527b4b22e35de17b8b48850c814fa4a5"}},["fields"]={["appearance"]="Odo had lost his sight but adapted his other senses, resembling the bats he kept.",["location"]="He occupied a decaying wooden structure projecting precariously from the keep.",["relationships"]="Two pet bats, a Blood Seeker and a Vile Bat, accompanied him."},["id"]="catalog-unit-4279",["kind"]="creature",["newSubject"]=false,["qualification"]="CLASSIC_HISTORICAL_CONTEXT_NOT_CURRENT_FOREVER_MECHANICS_OR_PERSONAL_EXPERIENCE",["related"]={"shadowfang-keep"},["sourceKey"]="wiki-odo",["sourceURL"]="https://warcraft.wiki.gg/wiki/Odo_the_Blindwatcher_%28Classic%29",["sourceVersion"]="instance-boss-histories-2026-10-26-r3",["title"]="Odo the Blindwatcher"},{["aliases"]={"Wolf Master Nandos"},["fieldEvidence"]={["context"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-nandos",["receiptSHA256"]="3b82c39021c30898e700c123634f54d294f0ce99fa66dafab8a047f4b9f7ed64"},["role"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-nandos",["receiptSHA256"]="3b82c39021c30898e700c123634f54d294f0ce99fa66dafab8a047f4b9f7ed64"}},["fields"]={["context"]="The Classic account placed him as the last of Arugal’s henchmen obstructing the ascent.",["role"]="Nandos was Arugal’s worgen handler of lesser worgs, whose own pack guarded the approach to him."},["id"]="catalog-unit-3927",["kind"]="creature",["newSubject"]=false,["qualification"]="CLASSIC_HISTORICAL_CONTEXT_NOT_CURRENT_FOREVER_MECHANICS_OR_PERSONAL_EXPERIENCE",["related"]={"shadowfang-keep"},["sourceKey"]="wiki-nandos",["sourceURL"]="http