on"},["fieldEvidence"]={["context"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-lore-keeper",["receiptSHA256"]="4d7e77ee7999fb466c50acd7b30d1642365870f1932155221aee80b4994c9f17"},["role"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-lore-keeper",["receiptSHA256"]="4d7e77ee7999fb466c50acd7b30d1642365870f1932155221aee80b4994c9f17"}},["fields"]={["context"]="Its account connected the earthen, troggs and dwarves to the titans’ experiments with subterranean life.",["role"]="The constructed watcher preserved and explained knowledge stored with the Discs of Norgannon."},["id"]="catalog-unit-7172",["kind"]="creature",["newSubject"]=false,["qualification"]="CLASSIC_HISTORICAL_CONTEXT_NOT_CURRENT_FOREVER_MECHANICS_OR_PERSONAL_EXPERIENCE",["related"]={"uldaman"},["sourceKey"]="wiki-lore-keeper",["sourceURL"]="https://warcraft.wiki.gg/wiki/Lore_Keeper_of_Norgannon",["sourceVersion"]="instance-boss-histories-2026-10-26-r3",["title"]="Lore Keeper of Norgannon"},{["aliases"]={"The Caller’s Chamber"},["fieldEvidence"]={["context"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-rfd",["receiptSHA256"]="4be1c0019a8579dc0d8e6dacc90c588e8496b4b78f0f66aaebcbeedfc29a8f11"}},["fields"]={["context"]="The chamber’s gong called forth the creatures associated with Tuten’kash’s original encounter."},["id"]="instance-place-the-caller-s-chamber",["kind"]="place",["newSubject"]=true,["qualification"]="CLASSIC_HISTORICAL_CONTEXT_NOT_CURRENT_FOREVER_MECHANICS_OR_PERSONAL_EXPERIENCE",["related"]={"atlas-instance-razorfen-downs"},["sourceKey"]="wiki-rfd",["sourceURL"]="https://warcraft.wiki.gg/wiki/Razorfen_Downs_%28Classic%29",["sourceVersion"]="instance-boss-histories-2026-10-26-r3",["title"]="The Caller’s Chamber"},{["aliases"]={"The Murder Pens"},["fieldEvidence"]={["relationships"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-rfd",["receiptSHA256"]="4be1c0019a8579dc0d8e6dacc90c588e8496b4b78f0f66aaebcbeedfc29a8f11"}},["fields"]={["relationships"]="Belnistrasz and Henry Stern were held among the burial grounds’ prisoners."},["id"]="instance-place-the-murder-pens",["kind"]="place",["newSubject"]=true,["qualification"]="CLASSIC_HISTORICAL_CONTEXT_NOT_CURRENT_FOREVER_MECHANICS_OR_PERSONAL_EXPERIENCE",["related"]={"atlas-instance-razorfen-downs"},["sourceKey"]="wiki-rfd",["sourceURL"]="https://warcraft.wiki.gg/wiki/Razorfen_Downs_%28Classic%29",["sourceVersion"]="instance-boss-histories-2026-10-26-r3",["title"]="The Murder Pens"},{["aliases"]={"The Bone Pile"},["fieldEvidence"]={["relationships"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-rfd",["receiptSHA256"]="4be1c0019a8579dc0d8e6dacc90c588e8496b4b78f0f66aaebcbeedfc29a8f11"}},["fields"]={["relationships"]="Mordresh Fire Eye stood above lesser undead among the bones."},["id"]="instance-place-the-bone-pile",["kind"]="place",["newSubject"]=true,["qualification"]="CLASSIC_HISTORICAL_CONTEXT_NOT_CURRENT_FOREVER_MECHANICS_OR_PERSONAL_EXPERIENCE",["related"]={"atlas-instance-razorfen-downs"},["sourceKey"]="wiki-rfd",["sourceURL"]="https://warcraft.wiki.gg/wiki/Razorfen_Downs_%28Classic%29",["sourceVersion"]="instance-boss-histories-2026-10-26-r3",["title"]="The Bone Pile"},{["aliases"]={"Spiral of Thorns"},["fieldEvidence"]={["relationships"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-rfd",["receiptSHA256"]="4be1c0019a8579dc0d8e6dacc90c588e8496b4b78f0f66aaebcbeedfc29a8f11"}},["fields"]={["relationships"]="Glutton and the rare quilboar Ragglesnout occupied the thorn-enclosed paths."},["id"]="instance-place-spiral-of-thorns",["kind"]="place",["newSubject"]=true,["qualification"]="CLASSIC_HISTORICAL_CONTEXT_NOT_CURRENT_FOREVER_MECHANICS_OR_PERSONAL_EXPERIENCE",["related"]={"atlas-instance-razorfen-downs"},["sourceKey"]="wiki-rfd",["sourceURL"]="https://warcraft.wiki.gg/wiki/Razorfen_Downs_%28Classic%29",["sourceVersion"]="instance-boss-histories-2026-10-26-r3",["title"]="Spiral of Thorns"},{["aliases"]={"Dig Three"},["fieldEvidence"]={["relationships"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-uldaman",["receiptSHA256"]="c722c746ed6e3a7a25319b508473f0eb7d11a95ca8d307c2635b8d394f521a31"}},["fields"]={["relationships"]="Dark Iron geologists and Galgann Firehammer occupied this excavation within Uldaman."},["id"]="instance-place-dig-three",["kind"]="place",["newSubject"]=true,["qualification"]="CLASSIC_HISTORICAL_CONTEXT_NOT_CURRENT_FOREVER_MECHANICS_OR_PERSONAL_EXPERIENCE",["related"]={"uldaman"},["sourceKey"]="wiki-uldaman",["sourceURL"]="https://warcraft.wiki.gg/wiki/ULD",["sourceVersion"]="instance-boss-histories-2026-10-26-r3",["title"]="Dig Three"},{["aliases"]={"The Stone Vault"},["fieldEvidence"]={["relationships"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-uldaman",["receiptSHA256"]="c722c746ed6e3a7a25319b508473f0eb7d11a95ca8d307c2635b8d394f521a31"}},["fields"]={["relationships"]="Stonevault troggs, Grimlok and his basilisk occupied this part of the ancient complex."},["id"]="instance-place-the-stone-vault",["kind"]="place",["newSubject"]=true,["qualification"]="CLASSIC_HISTORICAL_CONTEXT_NOT_CURRENT_FOREVER_MECHANICS_OR_PERSONAL_EXPERIENCE",["related"]={"uldaman"},["sourceKey"]="wiki-uldaman",["sourceURL"]="https://warcraft.wiki.gg/wiki/ULD",["sourceVersion"]="instance-boss-histories-2026-10-26-r3",["title"]="The Stone Vault"},{["aliases"]={"Hall of the Crafters"},["fieldEvidence"]={["relationships"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-uldaman",["receiptSHA256"]="c722c746ed6e3a7a25319b508473f0eb7d11a95ca8d307c2635b8d394f521a31"}},["fields"]={["relationships"]="Earthen workers and stone defenders remained within this interior hall."},["id"]="instance-place-hall-of-the-crafters",["kind"]="place",["newSubject"]=true,["qualification"]="CLASSIC_HISTORICAL_CONTEXT_NOT_CURRENT_FOREVER_MECHANICS_OR_PERSONAL_EXPERIENCE",["related"]={"uldaman"},["sourceKey"]="wiki-uldaman"