ace",["newSubject"]=false,["qualification"]="CLASSIC_HISTORICAL_CONTEXT_NOT_CURRENT_FOREVER_MECHANICS_OR_PERSONAL_EXPERIENCE",["related"]={"atlas-instance-scholomance"},["sourceKey"]="wiki-place-ravenian",["sourceURL"]="https://warcraft.wiki.gg/wiki/Vault_of_the_Ravenian",["sourceVersion"]="instance-boss-histories-2026-10-26-r3",["title"]="Vault of the Ravenian"},{["aliases"]={"Barov Family Vault"},["fieldEvidence"]={["appearance"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-place-barov-vault",["receiptSHA256"]="edd6efaf0b09534f59d320ec4ba7a515216762607c8c03eb3fdbaa7904f0e5bb"},["location"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-place-barov-vault",["receiptSHA256"]="edd6efaf0b09534f59d320ec4ba7a515216762607c8c03eb3fdbaa7904f0e5bb"}},["fields"]={["appearance"]="Skeletal warriors stood with the undead Lord Alexei Barov in his family’s vault.",["location"]="The vault lay through the lower eastern doorway of the Headmaster’s Study."},["id"]="instance-place-scholo-barov-family-vault",["kind"]="place",["newSubject"]=false,["qualification"]="CLASSIC_HISTORICAL_CONTEXT_NOT_CURRENT_FOREVER_MECHANICS_OR_PERSONAL_EXPERIENCE",["related"]={"atlas-instance-scholomance"},["sourceKey"]="wiki-place-barov-vault",["sourceURL"]="https://warcraft.wiki.gg/wiki/Barov_Family_Vault",["sourceVersion"]="instance-boss-histories-2026-10-26-r3",["title"]="Barov Family Vault"},{["aliases"]={"Festival Lane"},["fieldEvidence"]={["appearance"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-place-festival",["receiptSHA256"]="d368883b92fb488620fdc78cc8da73991b7b437b6ec532b2e21bde182100bc47"},["location"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-place-festival",["receiptSHA256"]="d368883b92fb488620fdc78cc8da73991b7b437b6ec532b2e21bde182100bc47"}},["fields"]={["appearance"]="Burning shops lined the lane, including Angelista’s Boutique, Pierce’s Pistols and Goodman’s General Goods.",["location"]="East of King’s Square, Festival Lane connected the Scarlet-held city with Elders’ Square in the original divided Stratholme."},["id"]="world-place-festival-lane",["kind"]="place",["newSubject"]=true,["qualification"]="CLASSIC_HISTORICAL_CONTEXT_NOT_CURRENT_FOREVER_MECHANICS_OR_PERSONAL_EXPERIENCE",["related"]={"stratholme"},["sourceKey"]="wiki-place-festival",["sourceURL"]="https://warcraft.wiki.gg/wiki/Festival_Lane",["sourceVersion"]="instance-boss-histories-2026-10-26-r3",["title"]="Festival Lane"},{["aliases"]={"Crusaders’ Square"},["fieldEvidence"]={["appearance"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-place-crusaders",["receiptSHA256"]="77a8a93de97f70325567aecd34ccce36fcf5f2943efdbb82e76887d3de4ce771"},["location"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-place-crusaders",["receiptSHA256"]="77a8a93de97f70325567aecd34ccce36fcf5f2943efdbb82e76887d3de4ce771"}},["fields"]={["appearance"]="Crates and rubble sheltered Crimson Legion defenders before the Scarlet Bastion.",["location"]="The square stood west of Market Row in the Scarlet-held half of Stratholme."},["id"]="world-place-crusaders-square",["kind"]="place",["newSubject"]=true,["qualification"]="CLASSIC_HISTORICAL_CONTEXT_NOT_CURRENT_FOREVER_MECHANICS_OR_PERSONAL_EXPERIENCE",["related"]={"stratholme"},["sourceKey"]="wiki-place-crusaders",["sourceURL"]="https://warcraft.wiki.gg/wiki/Crusaders%27_Square",["sourceVersion"]="instance-boss-histories-2026-10-26-r3",["title"]="Crusaders’ Square"},{["aliases"]={"Elders’ Square"},["fieldEvidence"]={["context"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-place-elders",["receiptSHA256"]="44e17e99932fa72a9d4abd9cc820393ca0f92d3cb6dfabc95cfffbff4fffdeeb"},["location"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-place-elders",["receiptSHA256"]="44e17e99932fa72a9d4abd9cc820393ca0f92d3cb6dfabc95cfffbff4fffdeeb"}},["fields"]={["context"]="Alonsus Chapel stood amid the square’s undead, its hallowed ground a surviving refuge within the ruined city.",["location"]="Just beyond the Service Entrance, the square opened north toward the Gauntlet and west toward Festival Lane."},["id"]="world-place-elders-square",["kind"]="place",["newSubject"]=true,["qualification"]="CLASSIC_HISTORICAL_CONTEXT_NOT_CURRENT_FOREVER_MECHANICS_OR_PERSONAL_EXPERIENCE",["related"]={"stratholme"},["sourceKey"]="wiki-place-elders",["sourceURL"]="https://warcraft.wiki.gg/wiki/Elders%27_Square",["sourceVersion"]="instance-boss-histories-2026-10-26-r3",["title"]="Elders’ Square"},{["aliases"]={"Alonsus Chapel"},["fieldEvidence"]={["context"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-place-alonsus",["receiptSHA256"]="4de5ab7935075fca26f096c3b853b664cd5e3e6097b75fc947b595db522ab6fe"},["location"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-place-alonsus",["receiptSHA256"]="4de5ab7935075fca26f096c3b853b664cd5e3e6097b75fc947b595db522ab6fe"}},["fields"]={["context"]="Aurius sheltered inside, where an eternal flame resisted the corruption surrounding the building.",["location"]="The chapel stood in Stratholme’s Elders’ Square."},["id"]="world-place-alonsus-chapel",["kind"]="place",["newSubject"]=true,["qualification"]="CLASSIC_HISTORICAL_CONTEXT_NOT_CURRENT_FOREVER_MECHANICS_OR_PERSONAL_EXPERIENCE",["related"]={"stratholme"},["sourceKey"]="wiki-place-alonsus",["sourceURL"]="https://warcraft.wiki.gg/wiki/Alonsus_Chapel",["sourceVersion"]="instance-boss-histories-2026-10-26-r3",["title"]="Alonsus Chapel"},{["aliases"]={"Aegwynn"},["fieldEvidence"]={["history"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-historical-aegwynn",["receiptSHA256"]="ddeabab5bdacbcddcf501e0d5fc763bc3fb733af11cc2079266f497e4fba7d85"},["motivation"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-historical-aegwynn",["receiptSHA256"]="ddeabab5bdacbcddcf501e0d5fc763bc3fb733af11cc2079266f497e4fba7d85"},["relationships"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-historical-aegwynn",["receiptSHA256"]="ddeabab5bdacbcddcf501e0d5fc763bc3fb733af11cc2079266f497e4fba7d85"},["role"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-historical-aegwynn",["receiptSHA256"]="ddeabab5bdacbcddcf501e0d5fc763bc3fb733af11cc2079266f497e4fba7d85"}},["fields"]={["history"]="She defeated Sargeras’s physical form and sealed it beneath the sea, unaware that his spirit had hidden within her.",["motivation"]="Distrusting the Council’s interference, she chose her own successor rather than yield that choice to its members.",["relationships"]="Her son Medivh, fathered by Nielas Aran, inherited the Guardian’s power and the concealed demonic threat.",["role"]="Aegwynn wielded the Guardian of Tirisfal’s power against the Burning Legion."},["id"]="atlas-figure-aegwynn",["kind"]="figure",["newSubject"]=false,["qualification"]="FIRST_AND_SECOND_WAR_HISTORY_ONLY; EXCLUDES_LATER_PLOTS_ALTERNATE_DRAENOR_AND_RETROACTIVE_PLAYER_DEEDS",["related"]={"stormwind"},["sourceKey"]="wiki-historical-aegwynn",["sourceURL"]="https://warcraft.wiki.gg/wiki/Guardian_Aegwyn",["sourceVersion"]="instance-boss-histories-2026-10-26-r3",["title"]="Aegwynn"},{["aliases"]={"Garona Halforcen"},["fieldEvidence"]={["conflict"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-historical-garona",["receiptSHA256"]="bb6b7915e05327b0fdd3ea00c6428f5e2c0e4fc3609b46222b44b3c36cc8e050"},["history"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-historical-garona",["receiptSHA256"]="bb6b7915e05327b0fdd3ea00c6428f5e2c0e4fc3609b46222b44b3c36cc8e050"},["relationships"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-historical-garona",["receiptSHA256"]="bb6b7915e05327b0fdd3ea00c6428f5e2c0e4fc3609b46222b44b3c36cc8e050"},["role"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-historical-garona",["receiptSHA256"]="bb6b7915e05327b0fdd3ea00c6428f5e2c0e4fc3609b46222b44b3c36cc8e050"}},["fields"]={["conflict"]="Llane had treated her kindly, yet compulsion and the damage inflicted at Karazhan drove her to become his reluctant assassin.",["history"]="After Llane’s murder, Doomhammer captured and tortured her for the Shadow Council’s location.",["relationships"]="She and Khadgar uncovered Medivh’s involvement in the invasion and carried the warning to Lothar and Llane.",["role"]="Garona served as a half-orc interpreter, emissary and assassin during the Horde’s first invasion."},["id"]="garona",["kind"]="figure",["newSubject"]=false,["qualification"]="FIRST_AND_SECOND_WAR_HISTORY_ONLY; EXCLUDES_LATER_PLOTS_ALTERNATE_DRAENOR_AND_RETROACTIVE_PLAYER_DEEDS",["related"]={"stormwind"},["sourceKey"]="wiki-historical-garona",["sourceURL"]="https://warcraft.wiki.gg/wiki/Garona_Halforcen",["sourceVersion"]="instance-boss-histories-2026-10-26-r3",["title"]="Garona Halforcen"},{["aliases"]={"Llane Wrynn I"},["fieldEvidence"]={["context"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-historical-llane",["receiptSHA256"]="63259ab701b8e9cbf1ff2cbbd595fdf09549378a4a4a93f5d84573d5d96fa120"},["relationships"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-historical-llane",["receiptSHA256"]="63259ab701b8e9cbf1ff2cbbd595fdf09549378a4a4a93f5d84573d5d96fa120"},["role"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-historical-llane",["receiptSHA256"]="63259ab701b8e9cbf1ff2cbbd595fdf09549378a4a4a93f5d84573d5d96fa120"}},["fields"]={["context"]="Reports of unfamiliar attackers in the Black Morass led him to send Lothar scouting. Repeated clashes revealed an invasion reinforced from a source the defenders had not found.",["relationships"]="Varian was his son; Lothar and Medivh had been his companions since childhood.",["role"]="Llane ruled Stormwind during the First War."},["id"]="instance-encounter-llane-wrynn-i",["kind"]="figure",["newSubject"]=true,["qualification"]="FIRST_AND_SECOND_WAR_HISTORY_ONLY; EXCLUDES_LATER_PLOTS_ALTERNATE_DRAENOR_AND_RETROACTIVE_PLAYER_DEEDS",["related"]={"stormwind"},["sourceKey"]="wiki-historical-llane",["sourceURL"]="https://warcraft.wiki.gg/wiki/Llane_Wrynn",["sourceVersion"]="instance-boss-histories-2026-10-26-r3",["title"]="Llane Wrynn I"},{["aliases"]={"Cho'gall"},["fieldEvidence"]={["context"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-historical-chogall",["receiptSHA256"]="fd64ebdef7448e6bab23cb6bb4c01ed0b2d8cf1f572c526c3935d1e204411673"},["history"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-historical-chogall",["receiptSHA256"]="fd64ebdef7448e6bab23cb6bb4c01ed0b2d8cf1f572c526c3935d1e204411673"},["motivation"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-historical-chogall",["receiptSHA256"]="fd64ebdef7448e6bab23cb6bb4c01ed0b2d8cf1f572c526c3935d1e204411673"},["role"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-historical-chogall",["receiptSHA256"]="fd64ebdef7448e6bab23cb6bb4c01ed0b2d8cf1f572c526c3935d1e204411673"}},["fields"]={["context"]="He and remnants of his clan survived the disaster that killed Gul’dan.",["history"]="He helped Gul’dan create death knights and ogre magi, then followed him away from the Horde’s war to seek the Tomb of Sargeras.",["motivation"]="His clan treated the coming apocalypse as a religious purpose rather than merely another conquest.",["role"]="Cho’gall was an ogre mage, Shadow Council initiate and chieftain of the Twilight’s Hammer."},["id"]="atlas-figure-chogall",["kind"]="figure",["newSubject"]=false,["qualification"]="FIRST_AND_SECOND_WAR_HISTORY_ONLY; EXCLUDES_LATER_PLOTS_ALTERNATE_DRAENOR_AND_RETROACTIVE_PLAYER_DEEDS",["related"]={"atlas-place-blasted-lands"},["sourceKey"]="wiki-historical-chogall",["sourceURL"]="https://warcraft.wiki.gg/wiki/Cho%27gall",["sourceVersion"]="instance-boss-histories-2026-10-26-r3",["title"]="Cho’gall"},{["aliases"]={"Gul'dan"},["fieldEvidence"]={["context"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-historical-guldan",["receiptSHA256"]="c74d2109f9958b8a6f6f16d7292aa670ae649bf988c6d5f37cebfa6912c40f57"},["history"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-historical-guldan",["receiptSHA256"]="c74d2109f9958b8a6f6f16d7292aa670ae649bf988c6d5f37cebfa6912c40f57"},["motivation"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-historical-guldan",["receiptSHA256"]="c74d2109f9958b8a6f6f16d7292aa670ae649bf988c6d5f37cebfa6912c40f57"},["relationships"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-historical-guldan",["receiptSHA256"]="c74d2109f9958b8a6f6f16d7292aa670ae649bf988c6d5f37cebfa6912c40f57"}},["fields"]={["context"]="After Doomhammer destroyed the Shadow Council, Gul’dan purchased survival by offering the new warchief an army of undead riders.",["history"]="The souls of slain warlocks were bound to fallen Stormwind knights, with sacrificed necrolytes’ power set into the death knights’ truncheons.",["motivation"]="His Stormreaver clan and secretly assembled fleet served ambitions beyond obedience to Doomhammer.",["relationships"]="Cho’gall and the Twilight’s Hammer remained among his supporters after Blackhand and most of the Council were gone."},["id"]="guldan",["kind"]="figure",["newSubject"]=false,["qualification"]="FIRST_AND_SECOND_WAR_HISTORY_ONLY; EXCLUDES_LATER_PLOTS_ALTERNATE_DRAENOR_AND_RETROACTIVE_PLAYER_DEEDS",["related"]={"atlas-place-blasted-lands"},["sourceKey"]="wiki-historical-guldan",["sourceURL"]="https://warcraft.wiki.gg/wiki/Gul%27dan",["sourceVersion"]="instance-boss-histories-2026-10-26-r3",["title"]="Gul’dan"},{["aliases"]={"Ner'zhul"},["fieldEvidence"]={["appearance"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-historical-nerzhul",["receiptSHA256"]="72a9955f5bfa8928fa9e02f50b571b86b836af851def9f3091fe7936970aa263"},["context"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-historical-nerzhul",["receiptSHA256"]="72a9955f5bfa8928fa9e02f50b571b86b836af851def9f3091fe7936970aa263"},["motivation"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-historical-nerzhul",["receiptSHA256"]="72a9955f5bfa8928fa9e02f50b571b86b836af851def9f3091fe7936970aa263"},["relationships"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-historical-nerzhul",["receiptSHA256"]="72a9955f5bfa8928fa9e02f50b571b86b836af851def9f3091fe7936970aa263"}},["fields"]={["appearance"]="The old shaman painted a white skull upon his face as visions of death consumed him.",["context"]="The great portal spell required powerful artifacts from Azeroth, including the Skull of Gul’dan, Book of Medivh and Scepter of Sargeras.",["motivation"]="He accepted Gorefiend’s plan to open paths to other worlds as an escape from Draenor’s feared destruction.",["relationships"]="Teron Gorefiend urged his return to leadership, while Dentarg enforced his authority over the clans."},["id"]="nerzhul",["kind"]="figure",["newSubject"]=false,["qualification"]="FIRST_AND_SECOND_WAR_HISTORY_ONLY; EXCLUDES_LATER_PLOTS_ALTERNATE_DRAENOR_AND_RETROACTIVE_PLAYER_DEEDS",["related"]={"atlas-place-blasted-lands"},["sourceKey"]="wiki-historical-nerzhul",["sourceURL"]="https://warcraft.wiki.gg/wiki/Ner%27zhul",["sourceVersion"]="instance-boss-histories-2026-10-26-r3",["title"]="Ner’zhul"},{["aliases"]={"Kilrogg Deadeye"},["fieldEvidence"]={["appearance"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-historical-kilrogg",["receiptSHA256"]="f3495ca4ac041f4a48a2b861b75b742bd18dcc66a280b0a5cb682783638d4b27"},["context"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-historical-kilrogg",["receiptSHA256"]="f3495ca4ac041f4a48a2b861b75b742bd18dcc66a280b0a5cb682783638d4b27"},["relationships"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-historical-kilrogg",["receiptSHA256"]="f3495ca4ac041f4a48a2b861b75b742bd18dcc66a280b0a5cb682783638d4b27"},["role"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-historical-kilrogg",["receiptSHA256"]="f3495ca4ac041f4a48a2b861b75b742bd18dcc66a280b0a5cb682783638d4b27"}},["fields"]={["appearance"]="Kilrogg’s missing left eye gave him the name Deadeye.",["context"]="His clan controlled important mining and oil-refining operations in Khaz Modan while the dwarves continued resisting from Ironforge.",["relationships"]="He fought under Blackhand and then Doomhammer, supporting the latter’s response to Gul’dan’s betrayal.",["role"]="The aging chieftain led the Bleeding Hollow through the First and Second Wars."},["id"]="atlas-figure-kilrogg-deadeye",["kind"]="figure",["newSubject"]=false,["qualification"]="FIRST_AND_SECOND_WAR_HISTORY_ONLY; EXCLUDES_LATER_PLOTS_ALTERNATE_DRAENOR_AND_RETROACTIVE_PLAYER_DEEDS",["related"]={"atlas-place-blasted-lands"},["sourceKey"]="wiki-historical-kilrogg",["sourceURL"]="https://warcraft.wiki.gg/wiki/Kilrogg_Deadeye",["sourceVersion"]="instance-boss-histories-2026-10-26-r3",["title"]="Kilrogg Deadeye"},{["aliases"]={"Teron Gorefiend"},["fieldEvidence"]={["context"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-historical-gorefiend",["receiptSHA256"]="3e8319f762843e97ad3aabb96fab34e4b2ff54b76d02275710b39bf4c201c2ad"},["history"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-historical-gorefiend",["receiptSHA256"]="3e8319f762843e97ad3aabb96fab34e4b2ff54b76d02275710b39bf4c201c2ad"},["relationships"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-historical-gorefiend",["receiptSHA256"]="3e8319f762843e97ad3aabb96fab34e4b2ff54b76d02275710b39bf4c201c2ad"},["role"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-historical-gorefiend",["receiptSHA256"]="3e8319f762843e97ad3aabb96fab34e4b2ff54b76d02275710b39bf4c201c2ad"}},["fields"]={["context"]="He led the search in Azeroth for the artifacts needed by Ner’zhul’s portal spell.",["history"]="The Shadow Council warlock Teron’gor was slain during Doomhammer’s purge. Gul’dan placed his soul in a dead Stormwind knight, creating the first of the Horde’s death knights.",["relationships"]="After returning to Draenor, he persuaded Ner’zhul to lead a renewed Horde and seek other worlds.",["role"]="Gorefiend commanded those undead sorcerers during the Second War."},["id"]="atlas-figure-teron-gorefiend",["kind"]="figure",["newSubject"]=false,["qualification"]="FIRST_AND_SECOND_WAR_HISTORY_ONLY; EXCLUDES_LATER_PLOTS_ALTERNATE_DRAENOR_AND_RETROACTIVE_PLAYER_DEEDS",["related"]={"atlas-place-blasted-lands"},["sourceKey"]="wiki-historical-gorefiend",["sourceURL"]="https://warcraft.wiki.gg/wiki/Teron_gorefiend",["sourceVersion"]="instance-boss-histories-2026-10-26-r3",["title"]="Teron Gorefiend"},{["aliases"]={"Dragonmaw Garrison"},["fieldEvidence"]={["appearance"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-place-bwl-garrison",["receiptSHA256"]="6ef002cd1969fc9481ff68d02165b894f7daa4dcf8ae316c6cb28fdf3732ca2a"},["context"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-place-bwl-garrison",["receiptSHA256"]="6ef002cd1969fc9481ff68d02165b894f7daa4dcf8ae316c6cb28fdf3732ca2a"},["relationships"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-place-bwl-garrison",["receiptSHA256"]="6ef002cd1969fc9481ff68d02165b894f7daa4dcf8ae316c6cb28fdf3732ca2a"}},["fields"]={["appearance"]="Dragon eggs filled the broad entrance chamber, watched by orc guards and black dragonspawn.",["context"]="In the original encounter, Razorgore’s own power could destroy the eggs when the orb’s control was turned against his keepers.",["relationships"]="Grethok controlled Razorgore through the Orb of Domination here."},["id"]="world-place-dragonmaw-garrison",["kind"]="place",["newSubject"]=true,["qualification"]="CLASSIC_HISTORICAL_CONTEXT_NOT_CURRENT_FOREVER_MECHANICS_OR_PERSONAL_EXPERIENCE",["related"]={"blackwing-lair"},["sourceKey"]="wiki-place-bwl-garrison",["sourceURL"]="https://warcraft.wiki.gg/wiki/Egg_Chamber",["sourceVersion"]="instance-boss-histories-2026-10-26-r3",["title"]="Dragonmaw Garrison"},{["aliases"]={"Halls of Strife"},["fieldEvidence"]={["conflict"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-place-bwl-strife",["receiptSHA256"]="26efeb217f677c5fcfcb6032441cf26559bbb6f3aec1fa2462234bc5eb16a17b"},["location"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-place-bwl-strife",["receiptSHA256"]="26efeb217f677c5fcfcb6032441cf26559bbb6f3aec1fa2462234bc5eb16a17b"},["relationships"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-place-bwl-strife",["receiptSHA256"]="26efeb217f677c5fcfcb6032441cf26559bbb6f3aec1fa2462234bc5eb16a17b"}},["fields"]={["conflict"]="Suppression devices hindered intruders through the gauntlet while hatchers and taskmasters tended corrupted whelps.",["location"]="The halls connected Shadow Wing Lair with the Crimson Laboratories.",["relationships"]="Death Talon dragonspawn guarded the approach to Broodlord Lashlayer."},["id"]="world-place-halls-of-strife",["kind"]="place",["newSubject"]=true,["qualification"]="CLASSIC_HISTORICAL_CONTEXT_NOT_CURRENT_FOREVER_MECHANICS_OR_PERSONAL_EXPERIENCE",["related"]={"blackwing-lair"},["sourceKey"]="wiki-place-bwl-strife",["sourceURL"]="https://warcraft.wiki.gg/wiki/Halls_of_Strife",["sourceVersion"]="instance-boss-histories-2026-10-26-r3",["title"]="Halls of Strife"},{["aliases"]={"Shadow Wing Lair"},["fieldEvidence"]={["appearance"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-place-bwl-shadow",["receiptSHA256"]="ff22ececd225403b79181becaf590a2bbd57030b67341cda335ce55fd55df88f"},["location"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-place-bwl-shadow",["receiptSHA256"]="ff22ececd225403b79181becaf590a2bbd57030b67341cda335ce55fd55df88f"},["relationships"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-place-bwl-shadow",["receiptSHA256"]="ff22ececd225403b79181becaf590a2bbd57030b67341cda335ce55fd55df88f"}},["fields"]={["appearance"]="A gray counterpart of the Valley of Kings monument stood here, with two thrones between its figures.",["location"]="The chamber lay directly beyond the Dragonmaw Garrison.",["relationships"]="Vaelastrasz struggled against Nefarius’s control within the hall."},["id"]="world-place-shadow-wing-lair",["kind"]="place",["newSubject"]=true,["qualification"]="CLASSIC_HISTORICAL_CONTEXT_NOT_CURRENT_FOREVER_MECHANICS_OR_PERSONAL_EXPERIENCE",["related"]={"blackwing-lair"},["sourceKey"]="wiki-place-bwl-shadow",["sourceURL"]="https://warcraft.wiki.gg/wiki/Shadow_Wing_Lair",["sourceVersion"]="instance-boss-histories-2026-10-26-r3",["title"]="Shadow Wing Lair"},{["aliases"]={"Crimson Laboratories"},["fieldEvidence"]={["context"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-place-bwl-crimson",["receiptSHA256"]="a41778b552d91c5ab046317567c847152aa0e7d645609e37913e3133cde721bc"},["location"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-place-bwl-crimson",["receiptSHA256"]="a41778b552d91c5ab046317567c847152aa0e7d645609e37913e3133cde721bc"},["relationships"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-place-bwl-crimson",["receiptSHA256"]="a41778b552d91c5ab046317567c847152aa0e7d645609e37913e3133cde721bc"},["role"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-place-bwl-crimson",["receiptSHA256"]="a41778b552d91c5ab046317567c847152aa0e7d645609e37913e3133cde721bc"}},["fields"]={["context"]="An alchemy laboratory beyond Lashlayer supported the old-world preparation of powerful flasks.",["location"]="The laboratories rose between the Halls of Strife and Nefarian’s throne chamber.",["relationships"]="Firemaw, Ebonroc and Flamegor patrolled these rooms, while a lever released Chromaggus from a separate chamber beyond them.",["role"]="Technicians, spellbinders and warlocks worked under the protection of drakes and Death Talon guards."},["id"]="world-place-crimson-laboratories",["kind"]="place",["newSubject"]=true,["qualification"]="CLASSIC_HISTORICAL_CONTEXT_NOT_CURRENT_FOREVER_MECHANICS_OR_PERSONAL_EXPERIENCE",["related"]={"blackwing-lair"},["sourceKey"]="wiki-place-bwl-crimson",["sourceURL"]="https://warcraft.wiki.gg/wiki/Crimson_Laboratories",["sourceVersion"]="instance-boss-histories-2026-10-26-r3",["title"]="Crimson Laboratories"},{["aliases"]={"Nefarian's Lair"},["fieldEvidence"]={["appearance"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-place-bwl-nefarian",["receiptSHA256"]="7cacdef06775593113d014be4bb104e07fce413269487ae2c80f7e9a4716159c"},["location"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-place-bwl-nefarian",["receiptSHA256"]="7cacdef06775593113d014be4bb104e07fce413269487ae2c80f7e9a4716159c"},["relationships"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-place-bwl-nefarian",["receiptSHA256"]="7cacdef06775593113d014be4bb104e07fce413269487ae2c80f7e9a4716159c"}},["fields"]={["appearance"]="A throne at the southeastern end overlooked the chamber, while the exposed height offered a view across the Searing Gorge.",["location"]="Beyond the Crimson Laboratories lay the black dragon’s final sanctuary within the lair.",["relationships"]="Nefarian occupied the throne in the human guise of Lord Victor Nefarius."},["id"]="world-place-nefarian-s-lair",["kind"]="place",["newSubject"]=true,["qualification"]="CLASSIC_HISTORICAL_CONTEXT_NOT_CURRENT_FOREVER_MECHANICS_OR_PERSONAL_EXPERIENCE",["related"]={"blackwing-lair"},["sourceKey"]="wiki-place-bwl-nefarian",["sourceURL"]="https://warcraft.wiki.gg/wiki/Nefarian%27s_Lair",["sourceVersion"]="instance-boss-histories-2026-10-26-r3",["title"]="Nefarian's Lair"},{["aliases"]={"Black Vault"},["fieldEvidence"]={["context"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-place-black-vault-detail",["receiptSHA256"]="5fe1bb