xt"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-place-chill-breeze",["receiptSHA256"]="d122aee6b59e19b5e3aa61970b6acc16fccac911e15e2506cdbc77f11ba62887"}},["fields"]={["appearance"]="Chill Breeze Valley formed a T-shaped passage between Gnomeregan in the west and Kharanos in the east.",["context"]="The frequently traveled east–west branch contrasted with the quieter northern and southern reaches, where bloodstained snow and torn animal remains warned of dangerous beasts."},["id"]="catalog-location-area-801",["kind"]="place",["newSubject"]=false,["qualification"]="CLASSIC_HISTORICAL_CONTEXT_NOT_CURRENT_FOREVER_MECHANICS_OR_PERSONAL_EXPERIENCE",["related"]={"dun-morogh"},["sourceKey"]="wiki-place-chill-breeze",["sourceURL"]="https://warcraft.wiki.gg/wiki/Chill_Breeze_Valley",["sourceVersion"]="instance-boss-histories-2026-10-26-r3",["title"]="Chill Breeze Valley"},{["aliases"]={"Bluefen"},["fieldEvidence"]={["appearance"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-place-bluefen",["receiptSHA256"]="84f2909c23797502b0db33f60d2e3d1df68eda65a61982d8091182cece21590d"}},["fields"]={["appearance"]="Bluefen was a marshy stretch of northern Dustwallow, with spiders, birds, raptors and crocolisks among its wildlife."},["id"]="catalog-location-area-507",["kind"]="place",["newSubject"]=false,["qualification"]="CLASSIC_HISTORICAL_CONTEXT_NOT_CURRENT_FOREVER_MECHANICS_OR_PERSONAL_EXPERIENCE",["related"]={"dustwallow"},["sourceKey"]="wiki-place-bluefen",["sourceURL"]="https://warcraft.wiki.gg/wiki/Bluefen",["sourceVersion"]="instance-boss-histories-2026-10-26-r3",["title"]="Bluefen"},{["aliases"]={"Broken Pillar"},["fieldEvidence"]={["appearance"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-place-broken-pillar",["receiptSHA256"]="ab67d349927ffcdb0c4e7ce14d3329474d95784d2c11312f2be3e88823b0c94c"},["context"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-place-broken-pillar",["receiptSHA256"]="ab67d349927ffcdb0c4e7ce14d3329474d95784d2c11312f2be3e88823b0c94c"}},["fields"]={["appearance"]="A small group of troll ruins stood south of Gadgetzan and east of the Abyssal Sands.",["context"]="Marvon Rivetseeker established a research camp at the Broken Pillar to investigate the ruins."},["id"]="catalog-location-area-1938",["kind"]="place",["newSubject"]=false,["qualification"]="CLASSIC_HISTORICAL_CONTEXT_NOT_CURRENT_FOREVER_MECHANICS_OR_PERSONAL_EXPERIENCE",["related"]={"atlas-place-tanaris"},["sourceKey"]="wiki-place-broken-pillar",["sourceURL"]="https://warcraft.wiki.gg/wiki/Broken_Pillar",["sourceVersion"]="instance-boss-histories-2026-10-26-r3",["title"]="Broken Pillar"},{["aliases"]={"Bloodtooth Camp"},["fieldEvidence"]={["conflict"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-place-bloodtooth",["receiptSHA256"]="496e9666cb59a3821bb37129a83245d2b85b9f0edb09bcac5074cae60a4a3271"},["location"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-place-bloodtooth",["receiptSHA256"]="496e9666cb59a3821bb37129a83245d2b85b9f0edb09bcac5074cae60a4a3271"}},["fields"]={["conflict"]="Ran Bloodtooth led the corrupted furbolgs who held the camp and attacked outsiders.",["location"]="Bloodtooth Camp lay west of the Falfarren River and southwest of Ashenvale’s southern moonwell."},["id"]="catalog-location-area-2357",["kind"]="place",["newSubject"]=false,["qualification"]="CLASSIC_HISTORICAL_CONTEXT_NOT_CURRENT_FOREVER_MECHANICS_OR_PERSONAL_EXPERIENCE",["related"]={"ashenvale"},["sourceKey"]="wiki-place-bloodtooth",["sourceURL"]="https://warcraft.wiki.gg/wiki/Bloodtooth_Camp",["sourceVersion"]="instance-boss-histories-2026-10-26-r3",["title"]="Bloodtooth Camp"},{["aliases"]={"Grizzlepaw Ridge"},["fieldEvidence"]={["appearance"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-place-grizzlepaw",["receiptSHA256"]="941f4c0b9a1c13372a38f0ce4eb480c488adbd611df6a357b8d89f9bd8c49777"},["context"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-place-grizzlepaw",["receiptSHA256"]="941f4c0b9a1c13372a38f0ce4eb480c488adbd611df6a357b8d89f9bd8c49777"}},["fields"]={["appearance"]="Grizzlepaw Ridge was mountainous ground south of Thelsamar and east of Stonesplinter Valley.",["context"]="Bears inhabited the ridge, including Ol’ Sooty, who sometimes left his lair for the valley below."},["id"]="catalog-location-area-936",["kind"]="place",["newSubject"]=false,["qualification"]="CLASSIC_HISTORICAL_CONTEXT_NOT_CURRENT_FOREVER_MECHANICS_OR_PERSONAL_EXPERIENCE",["related"]={"atlas-place-loch-modan"},["sourceKey"]="wiki-place-grizzlepaw",["sourceURL"]="https://warcraft.wiki.gg/wiki/Grizzlepaw_Ridge",["sourceVersion"]="instance-boss-histories-2026-10-26-r3",["title"]="Grizzlepaw Ridge"},{["aliases"]={"Misty Pine Refuge"},["fieldEvidence"]={["relationships"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-place-misty-pine",["receiptSHA256"]="6bfa74a500cbefcbe450f58962f1d069ccd574b8a83b7297d68258b73202f1ab"},["role"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-place-misty-pine",["receiptSHA256"]="6bfa74a500cbefcbe450f58962f1d069ccd574b8a83b7297d68258b73202f1ab"}},["fields"]={["relationships"]="Father Gavin represented the Argent Dawn at the refuge.",["role"]="Misty Pine Refuge housed an Argent Dawn outpost in central Dun Morogh."},["id"]="catalog-location-area-138",["kind"]="place",["newSubject"]=false,["qualification"]="CLASSIC_HISTORICAL_CONTEXT_NOT_CURRENT_FOREVER_MECHANICS_OR_PERSONAL_EXPERIENCE",["related"]={"dun-morogh"},["sourceKey"]="wiki-place-misty-pine",["sourceURL"]="https://warcraft.wiki.gg/wiki/Misty_Pine_Refuge",["sourceVersion"]="instance-boss-histories-2026-10-26-r3",["title"]="Misty Pine Refuge"},{["aliases"]={"The Dead Field"},["fieldEvidence"]={["appearance"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-place-dead-field",["receiptSHA256"]="f1776241c26fc2e88a3ab94eabeafdf56d5264fbcb43396a3fd2247e767f5d9a"},