qualification"]="CLASSIC_HISTORICAL_CONTEXT_NOT_CURRENT_FOREVER_MECHANICS_OR_PERSONAL_EXPERIENCE",["related"]={"atlas-place-swamp-of-sorrows"},["sourceKey"]="wiki-place-misty-reed-strand",["sourceURL"]="https://warcraft.wiki.gg/wiki/Misty_Reed_Strand",["sourceVersion"]="instance-boss-histories-2026-10-26-r3",["title"]="Misty Reed Strand"},{["aliases"]={"Owl Wing Thicket"},["fieldEvidence"]={["appearance"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-place-owl-wing-thicket",["receiptSHA256"]="d47ee24d144ecd8237e3717609d32cd4da69c073488281818c6212e78b4da4f7"},["context"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-place-owl-wing-thicket",["receiptSHA256"]="d47ee24d144ecd8237e3717609d32cd4da69c073488281818c6212e78b4da4f7"},["relationships"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-place-owl-wing-thicket",["receiptSHA256"]="d47ee24d144ecd8237e3717609d32cd4da69c073488281818c6212e78b4da4f7"}},["fields"]={["appearance"]="Owl Wing Thicket was a series of caves in southern Winterspring.",["context"]="Ranshalla guided the investigation of the ancient Guardians of Elune and the moonkin’s origins there.",["relationships"]="Berserk, moontouched and crazed owlbeasts occupied the thicket."},["id"]="catalog-location-area-2250",["kind"]="place",["newSubject"]=false,["qualification"]="CLASSIC_HISTORICAL_CONTEXT_NOT_CURRENT_FOREVER_MECHANICS_OR_PERSONAL_EXPERIENCE",["related"]={"atlas-place-winterspring"},["sourceKey"]="wiki-place-owl-wing-thicket",["sourceURL"]="https://warcraft.wiki.gg/wiki/Owl_Wing_Thicket",["sourceVersion"]="instance-boss-histories-2026-10-26-r3",["title"]="Owl Wing Thicket"},{["aliases"]={"Olsen's Farthing"},["fieldEvidence"]={["appearance"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-place-olsens-farthing",["receiptSHA256"]="5681d2b18dfe1110a0f7b89c48dac4354490f5892f2a349f9cb3d821b09c2ef4"},["conflict"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-place-olsens-farthing",["receiptSHA256"]="5681d2b18dfe1110a0f7b89c48dac4354490f5892f2a349f9cb3d821b09c2ef4"},["history"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-place-olsens-farthing",["receiptSHA256"]="5681d2b18dfe1110a0f7b89c48dac4354490f5892f2a349f9cb3d821b09c2ef4"}},["fields"]={["appearance"]="By the years after the Third War, the old farm lay ruined and overgrown with weeds.",["conflict"]="Ravenclaw slaves and raiders under Thule’s control attacked those entering the area.",["history"]="Olsen’s Farthing had once been a busy farmstead connected to Silverpine’s main trade route."},["id"]="catalog-location-area-229",["kind"]="place",["newSubject"]=false,["qualification"]="CLASSIC_HISTORICAL_CONTEXT_NOT_CURRENT_FOREVER_MECHANICS_OR_PERSONAL_EXPERIENCE",["related"]={"silverpine-forest"},["sourceKey"]="wiki-place-olsens-farthing",["sourceURL"]="https://warcraft.wiki.gg/wiki/Olsen%27s_Farthing",["sourceVersion"]="instance-boss-histories-2026-10-26-r3",["title"]="Olsen's Farthing"},{["aliases"]={"Oneiros"},["fieldEvidence"]={["appearance"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-place-oneiros",["receiptSHA256"]="cf924431c149a5e7384eb572a76cc92a7f520a52646bcfcc5eb8bc9e3f770b7d"},["location"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-place-oneiros",["receiptSHA256"]="cf924431c149a5e7384eb572a76cc92a7f520a52646bcfcc5eb8bc9e3f770b7d"}},["fields"]={["appearance"]="Night elven ruins filled the area, patrolled by powerful green dragonspawn in the older world.",["location"]="Oneiros lay south of Jademir Lake in northern Feralas."},["id"]="catalog-location-area-1113",["kind"]="place",["newSubject"]=false,["qualification"]="CLASSIC_HISTORICAL_CONTEXT_NOT_CURRENT_FOREVER_MECHANICS_OR_PERSONAL_EXPERIENCE",["related"]={"feralas"},["sourceKey"]="wiki-place-oneiros",["sourceURL"]="https://warcraft.wiki.gg/wiki/Oneiros",["sourceVersion"]="instance-boss-histories-2026-10-26-r3",["title"]="Oneiros"},{["aliases"]={"Ortell's Hideout"},["fieldEvidence"]={["appearance"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-place-ortell-hideout",["receiptSHA256"]="682d51a6827ce1f8c54d5a986804958a7c68e62f918e05cc6980f244dd63f5ae"}},["fields"]={["appearance"]="Hermit Ortell lived in a small cave in southeastern Silithus."},["id"]="catalog-location-area-3447",["kind"]="place",["newSubject"]=false,["qualification"]="CLASSIC_HISTORICAL_CONTEXT_NOT_CURRENT_FOREVER_MECHANICS_OR_PERSONAL_EXPERIENCE",["related"]={"atlas-place-silithus"},["sourceKey"]="wiki-place-ortell-hideout",["sourceURL"]="https://warcraft.wiki.gg/wiki/Ortell%27s_Hideout",["sourceVersion"]="instance-boss-histories-2026-10-26-r3",["title"]="Ortell's Hideout"},{["aliases"]={"Lakeridge Highway"},["fieldEvidence"]={["conflict"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-place-lakeridge-highway",["receiptSHA256"]="db8ba05239f9b331a34f76f2c2f361df722137084d7579171c42feed038c47cd"},["history"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-place-lakeridge-highway",["receiptSHA256"]="db8ba05239f9b331a34f76f2c2f361df722137084d7579171c42feed038c47cd"},["location"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-place-lakeridge-highway",["receiptSHA256"]="db8ba05239f9b331a34f76f2c2f361df722137084d7579171c42feed038c47cd"}},["fields"]={["conflict"]="Gnolls patrolled much of the abandoned highway, making travel dangerous.",["history"]="Once heavily traveled before the First War, the road fell into disuse after orcs seized Stonewatch Keep.",["location"]="Lakeridge Highway followed Lake Everstill’s southern shore through the Redridge Mountains."},["id"]="catalog-location-area-1001",["kind"]="place",["newSubject"]=false,["qualification"]="CLASSIC_HISTORICAL_CONTEXT_NOT_CURRENT_FOREVER_MECHANICS_OR_PERSONAL_EXPERIENCE",["related"]={"redridge-mountains"},["sourceKey"]="wiki-place-lakeridge-highway",["sourceURL"]="https://warcraft.wiki.gg/wiki/Lakeridge_Highway",["sourceVersion"]="instance-boss-histories-2026-10-26-r3",["title"]="Lakeridge Highway"},{["aliases"]={"Morlos'Aran"},["fieldEvidence"]={["appearance"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-place-morlos-aran",["receiptSHA256"]="f7d5752b78837a02be3588fd67ab1466edf859c0a59d89b616fd92fcfb963a89"},["history"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-place-morlos-aran",["receiptSHA256"]="f7d5752b78837a02be3588fd67ab1466edf859c0a59d89b616fd92fcfb963a89"}},["fields"]={["appearance"]="Its ruins at Felwood’s southern edge survived as a reminder of the lost age, resembling the other ancient Aran settlements scattered through Kalimdor.",["history"]="Morlos’Aran had been a great night elven settlement before the Sundering."},["id"]="catalog-location-area-2478",["kind"]="place",["newSubject"]=false,["qualification"]="CLASSIC_HISTORICAL_CONTEXT_NOT_CURRENT_FOREVER_MECHANICS_OR_PERSONAL_EXPERIENCE",["related"]={"atlas-place-felwood"},["sourceKey"]="wiki-place-morlos-aran",["sourceURL"]="https://warcraft.wiki.gg/wiki/Morlos%27Aran",["sourceVersion"]="instance-boss-histories-2026-10-26-r3",["title"]="Morlos'Aran"},{["aliases"]={"North Tide's Hollow"},["fieldEvidence"]={["location"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-place-north-tide-hollow",["receiptSHA256"]="6c04a0be40cf36d6b49768221e29b112e69c7ed3a67af2ea8fc809857191f463"},["role"]={["method"]="PUBLIC_INDEXED_SECONDARY_EXCERPT",["receiptID"]="wiki-place-north-tide-hollow",["receiptSHA256"]="6c04a0be40cf36d6b49768221e29b112e69c7ed3a67af2ea8fc809857191f463"}},["fields"]={["location"]="North Tide’s Hollow lay north of the Sepulcher in Silverpine Forest.",["role"]="Moonrage worgen serving Arugal made crude camps there, furnished with little beyond the necessities of survival."},["id"]="catalog-location-area-928",["kind"]="place",["newSubject"]=false,["qualification"]="CLASSIC_HISTORICAL_CONTEXT_NOT_CURRENT_FOREVER_MECHANICS_OR_PERSONAL_EXPERIENC