local byID={};for _,e in ipairs(D.entries)do byID[e.id]=e end
local function unique(t,v)for _,x in ipairs(t)do if x==v then return end end;t[#t+1]=v end
for _,r in ipairs(rows)do
 local e=byID[r.id]
 if r.newSubject then
  assert(not e,'Duplicate authored boss');e={id=r.id,title=r.title,kind=r.kind,fields={},aliases={},related={},gate='DISCOVERY',sourceURL=r.sourceURL,journalFields={}}
  D.entries[#D.entries+1]=e;byID[e.id]=e
 else assert(e and e.title==r.title,'Changed canonical boss')end
 e.fieldSources=e.fieldSources or {};e.fieldEvidence=e.fieldEvidence or {};e.fieldVersions=e.fieldVersions or {}
 for field,text in pairs(r.fields)do
  local old=e.fields[field]
  local bareReference=type(old)=='string' and ((field=='role' and old:find('Reference rank:',1,true)==1) or (field=='location' and (old:find('Reference location:',1,true)==1 or old:find('Location:',1,true)==1)) or (field=='context' and old:find('Reference level:',1,true)==1))
  if not old or old=='UNKNOWN' or bareReference then
   e.fields[field]=text;e.fieldSources[field]=r.sourceURL;e.fieldEvidence[field]=r.fieldEvidence[field];e.fieldVersions[field]=r.sourceVersion
   e.codexEnriched=true;e.catalogReferenceOnly=false
   if e.journalFields then unique(e.journalFields,field)end
   e.referenceStatus='PARTIALLY_AUTHORED_BOSS_CONTEXT_NOT_FULL_BIOGRAPHY'
  end
 end
 e.aliases=e.aliases or {};for _,v in ipairs(r.aliases)do unique(e.aliases,v)end
 e.related=e.related or {};for _,v in ipairs(r.related)do unique(e.related,v)end
 e.referenceQualification=r.qualification
end
